                <div class="card-body">
                    <h5 class="card-title">Course Info</h5>
                    <dl>
                        <dt>Credits</dt>
                        <dd>@course.Credits</dd>
                        <dt>Department</dt>
                        <dd>@(department?.Name ?? "Unknown")</dd>
                        <dt>Course Code</dt>
                        <dd>@course.Code</dd>
                    </dl>
